import type { CodegenConfig } from "@graphql-codegen/cli";

/**
 * GraphQL Code Generator — `npm run codegen` (or `npm run codegen:watch`).
 *
 * The schema comes from the mock AEM (mock-aem/schema.graphql, regenerated by `npm run mock:schema`).
 * Against a real AEM you would point `schema` at the endpoint instead, e.g.
 *   schema: { "https://publish-p1-e2.adobeaemcloud.com/content/cq:graphql/wknd-shared/endpoint.json": {} }
 * or download it from /content/cq:graphql/<config>/endpoint.GQLschema.
 */

// AEM's custom scalars, mapped to the TypeScript types you get over JSON.
const scalars = {
  Calendar: "string",
  Date: "string",
  Time: "string",
  JSON: "unknown",
};

const clientPreset = (folder: string) => ({
  documents: [`${folder}/**/*.{ts,tsx}`, `!${folder}/gql/**`, `!${folder}/**/*.test.{ts,tsx}`],
  preset: "client" as const,
  presetConfig: {
    // `getFragmentData` instead of the default `useFragment` (which is not a React hook and
    // would be confused with Apollo's useFragment).
    fragmentMasking: { unmaskFunctionName: "getFragmentData" },
  },
  config: {
    scalars,
    enumsAsTypes: true,
    useTypeImports: true,
  },
});

const config: CodegenConfig = {
  schema: "mock-aem/schema.graphql",
  ignoreNoDocuments: true,
  generates: {
    "src/labs/06-graphql-codegen/gql/": clientPreset("src/labs/06-graphql-codegen"),
    "src/solutions/06-graphql-codegen/gql/": clientPreset("src/solutions/06-graphql-codegen"),
    "src/labs/15-aem-capstone/gql/": clientPreset("src/labs/15-aem-capstone"),
    "src/solutions/15-aem-capstone/gql/": clientPreset("src/solutions/15-aem-capstone"),
  },
};

export default config;
